        var slotLiteral = new System.Text.RegularExpressions.Regex("\\G\\s*rb\"((?:[^\"\\\\]|\\\\.)*)\"");
        var slotCallEnd = new System.Text.RegularExpressions.Regex("\\G\\s*\\)");
