                if (interpolated && (d == '{' || d == '}') && j + 1 < cs.Length && cs[j + 1] == d) { j++; continue; }
                if (interpolated && d == '{') { int hole = CsClose(cs, j + 1, '}'); if (hole < 0) return cs.Length; j = hole; continue; }
