                var twStopReqs = Since(before);
                Check("/server/tweaks stop posts the counted body {\"version\":\"1.6\",\"cancel\":true}, once, with the token, and returns {ok, stopping}"
                      + (twStopErr is null ? "" : $" ({twStopErr})"),
