                      + (acctsErr is null ? "" : $" ({acctsErr})") + (acctsReqs.Count == 1 ? $" — sent {acctsReqs[0].path}" : ""),
                    acctsReqs.Count == 1 && acctsReqs[0].method == "GET" && acctsReqs[0].path == "/server/accounts?version=2.8&after=1000&limit=100&q=fri%20end%2B%26%3D%C3%9C"
